// @generated by:gauntlet run:godseye-local-database
import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  type DatabaseFixture,
  databaseFixture,
  databaseState,
  fixtureProfile,
} from "./pg-helpers.js";

describe("renewed database authority preserves exact existing physical identity", () => {
  let fixture: DatabaseFixture;
  beforeEach(async () => {
    fixture = await databaseFixture();
  });
  afterEach(async () => fixture.store.close());
  async function refreshObservation() {
    const inventory = await fixture.infrastructure.overview(fixture.freshOwner());
    const observation = fixture.configuration.collector.observation;
    observation.observedAt = fixture.clock.now().toISOString();
    observation.expiresAt = new Date(fixture.clock.now().getTime() + 300_000).toISOString();
    await fixture.infrastructure.refreshInventory(
      fixture.freshOwner(),
      { expectedRevision: inventory.observationRevision },
      randomUUID(),
    );
  }

  it("T-AC-27 T-AC-32 renews renamed scope and observation authority while retaining the exact cluster for suspension", async () => {
    const { preparation, allocation } = await fixture.admit();
    await fixture.infrastructure.foundation.tick("database-before-rename-worker");
    const before = structuredClone(fixture.provider.resources.get(allocation.id));
    await fixture.core.updateProject(
      fixture.freshOwner(),
      fixture.project.id,
      {
        expectedRevision: fixture.project.revision,
        name: "Renamed managed project",
        description: "",
      },
      randomUUID(),
    );
    await refreshObservation();
    await expect(
      fixture.infrastructure.database.admit(
        fixture.freshOwner(),
        { preparationId: preparation.id, expectedHash: preparation.hash, intent: "suspend" },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409 });
    const renewed = await fixture.prepare();
    expect(renewed).toMatchObject({ allocationId: allocation.id, expectedProjectRevision: 1 });
    expect(renewed.id).not.toBe(preparation.id);
    expect(renewed.hash).not.toBe(preparation.hash);
    await fixture.infrastructure.database.admit(
      fixture.freshOwner(),
      { preparationId: renewed.id, expectedHash: renewed.hash, intent: "suspend" },
      randomUUID(),
    );
    await fixture.infrastructure.foundation.tick("database-renewed-suspend-worker");
    expect(await databaseState(fixture, allocation.id)).toMatchObject({ state: "suspended" });
    expect(fixture.provider.resources.get(allocation.id)).toMatchObject({
      systemIdentifier: before?.systemIdentifier,
      providerRef: before?.providerRef,
      running: false,
    });
    expect(fixture.provider.effects.map((effect) => effect.action)).toEqual([
      "provision",
      "suspend",
    ]);
  });

  it("T-AC-28 refuses physical reprofiling when renewing an existing allocation", async () => {
    const { allocation } = await fixture.admit();
    await fixture.infrastructure.foundation.tick("database-fixed-profile-worker");
    await expect(
      fixture.infrastructure.database.prepare(
        fixture.freshOwner(),
        {
          projectId: fixture.project.id,
          environmentId: fixture.development.id,
          expectedProjectRevision: fixture.project.revision,
          expectedEnvironmentRevision: fixture.development.revision,
          profile: { ...fixtureProfile, maxConnections: fixtureProfile.maxConnections + 1 },
        },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409, code: "PROFILE_IMMUTABLE" });
    expect(await databaseState(fixture, allocation.id)).toMatchObject({ state: "ready" });
    expect(fixture.provider.effects).toHaveLength(1);
  });

  it("T-AC-32 retries a queued cancelled suspension using the last verified physical generation", async () => {
    const { preparation, allocation } = await fixture.admit();
    await fixture.infrastructure.foundation.tick("database-before-queued-stop-worker");
    const input = {
      preparationId: preparation.id,
      expectedHash: preparation.hash,
      intent: "suspend" as const,
    };
    const cancelled = await fixture.infrastructure.database.admit(
      fixture.freshOwner(),
      input,
      randomUUID(),
    );
    await fixture.infrastructure.foundation.cancel(
      fixture.freshOwner(),
      cancelled.runId,
      randomUUID(),
    );
    expect(await databaseState(fixture, allocation.id)).toMatchObject({ state: "ready" });
    expect(fixture.provider.resources.get(allocation.id)?.running).toBe(true);
    await fixture.infrastructure.database.admit(fixture.freshOwner(), input, randomUUID());
    await fixture.infrastructure.foundation.tick("database-retry-queued-stop-worker");
    expect(await databaseState(fixture, allocation.id)).toMatchObject({ state: "suspended" });
    expect(fixture.provider.resources.get(allocation.id)?.running).toBe(false);
    expect(fixture.provider.effects.map((effect) => effect.action)).toEqual([
      "provision",
      "suspend",
    ]);
  });

  it("T-AC-32 reconciles an unknown provision after observation expiry and renewal without repeating a physical mutation", async () => {
    fixture.provider.lostAcknowledgments.add("provision");
    const { allocation } = await fixture.admit();
    await fixture.infrastructure.foundation.tick("database-before-proof-renewal-worker");
    expect(await databaseState(fixture, allocation.id)).toMatchObject({ state: "unknown" });
    const before = structuredClone(fixture.provider.resources.get(allocation.id));
    fixture.clock.advance(301_000);
    await refreshObservation();
    await fixture.infrastructure.foundation.reconcile(
      fixture.freshOwner(),
      allocation.runId,
      randomUUID(),
    );
    expect(await databaseState(fixture, allocation.id)).toMatchObject({ state: "ready" });
    expect(fixture.provider.resources.get(allocation.id)).toEqual(before);
    expect(fixture.provider.effects).toEqual([
      { action: "provision", allocationId: allocation.id },
    ]);
  });

  it("T-AC-27 T-AC-32 permits a fresh exact protective suspension of an expired preview but denies resumption", async () => {
    const expiresAt = new Date(Date.now() + 60_000).toISOString();
    const current = await fixture.core.createEnvironment(
      fixture.freshOwner(),
      fixture.project.id,
      {
        expectedProjectRevision: fixture.project.revision,
        kind: "preview",
        name: "expiring-review",
        expiresAt,
        cpuMilliCores: 1000,
        memoryMiB: 2048,
        diskGiB: 20,
      },
      randomUUID(),
    );
    const environment = current.environments.find((item) => item.kind === "preview");
    if (!environment) throw new Error("Preview fixture missing");
    const { allocation } = await fixture.admit(environment.id);
    await fixture.infrastructure.foundation.tick("database-preview-worker");
    fixture.clock.advance(Date.parse(expiresAt) - fixture.clock.now().getTime() + 1);
    const renewed = await fixture.prepare(environment.id);
    expect(renewed.allocationId).toBe(allocation.id);
    await fixture.infrastructure.database.admit(
      fixture.freshOwner(),
      { preparationId: renewed.id, expectedHash: renewed.hash, intent: "suspend" },
      randomUUID(),
    );
    await fixture.infrastructure.foundation.tick("database-expired-preview-stop-worker");
    expect(await databaseState(fixture, allocation.id)).toMatchObject({ state: "suspended" });
    await expect(
      fixture.infrastructure.database.admit(
        fixture.freshOwner(),
        { preparationId: renewed.id, expectedHash: renewed.hash, intent: "resume" },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409, code: "ENVIRONMENT_EXPIRED" });
    expect(fixture.provider.resources.get(allocation.id)?.running).toBe(false);
  });
});
